-- Baseline schema for Lost or Found (public schema, functions, triggers, RLS, grants).
--
-- Source: `supabase db dump` (schema only, no data) of the production project
-- on 2026-10-27, after T1.8E.5J. Production already has this schema; it is marked
-- as applied there with `supabase migration repair` and is only executed when a
-- new database (staging, local, restore) is built from scratch.
--
-- Earlier hand-applied migrations are kept for history in supabase/legacy_migrations/
-- and are fully contained in this baseline. Do not edit this file; add new
-- migrations with a later 14-digit timestamp instead.



SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA "pg_catalog";






COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "btree_gist" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pg_trgm" WITH SCHEMA "public";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "postgis" WITH SCHEMA "public";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






CREATE TYPE "public"."match_status" AS ENUM (
    'NEW',
    'SEEN',
    'DISMISSED',
    'CONFIRMED',
    'PAID'
);


ALTER TYPE "public"."match_status" OWNER TO "postgres";


CREATE TYPE "public"."report_type" AS ENUM (
    'LOST',
    'FOUND'
);


ALTER TYPE "public"."report_type" OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."notification_watch_areas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "center" "public"."geography"(Point,4326) NOT NULL,
    "radius_m" integer NOT NULL,
    "category_keys" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "all_categories" boolean DEFAULT true NOT NULL,
    "push_enabled" boolean DEFAULT true NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "area_type" "text" DEFAULT 'CIRCLE'::"text" NOT NULL,
    "boundary" "public"."geography"(Polygon,4326),
    "source_type" "text" DEFAULT 'SAVED'::"text" NOT NULL,
    "expires_at" timestamp with time zone,
    "location_updated_at" timestamp with time zone,
    CONSTRAINT "notification_watch_areas_area_type_check" CHECK (("area_type" = ANY (ARRAY['CIRCLE'::"text", 'POLYGON'::"text"]))),
    CONSTRAINT "notification_watch_areas_geometry_check" CHECK (((("area_type" = 'CIRCLE'::"text") AND ("center" IS NOT NULL) AND ("radius_m" IS NOT NULL) AND ("radius_m" > 0) AND ("boundary" IS NULL)) OR (("area_type" = 'POLYGON'::"text") AND ("boundary" IS NOT NULL)))),
    CONSTRAINT "notification_watch_areas_radius_m_check" CHECK (((("area_type" = 'CIRCLE'::"text") AND ("radius_m" = ANY (ARRAY[250, 500, 1000, 3000, 5000, 10000]))) OR (("area_type" = 'POLYGON'::"text") AND ("radius_m" = 1)))),
    CONSTRAINT "notification_watch_areas_source_type_check" CHECK (("source_type" = ANY (ARRAY['SAVED'::"text", 'CURRENT_LOCATION'::"text"])))
);


ALTER TABLE "public"."notification_watch_areas" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user_watch_area"("p_user_id" "uuid", "p_name" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_m" integer, "p_category_keys" "text"[], "p_all_categories" boolean, "p_push_enabled" boolean) RETURNS SETOF "public"."notification_watch_areas"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query insert into public.notification_watch_areas(
    user_id,name,center,radius_m,category_keys,all_categories,push_enabled
  ) values (
    p_user_id,p_name,st_setsrid(st_makepoint(p_lng,p_lat),4326)::geography,
    p_radius_m,coalesce(p_category_keys,'{}'::text[]),p_all_categories,p_push_enabled
  ) returning *;
end;
$$;


ALTER FUNCTION "public"."create_user_watch_area"("p_user_id" "uuid", "p_name" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_m" integer, "p_category_keys" "text"[], "p_all_categories" boolean, "p_push_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user_watch_area_v2"("p_user_id" "uuid", "p_name" "text", "p_area_type" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_m" integer, "p_boundary_points" "jsonb", "p_category_keys" "text"[], "p_all_categories" boolean, "p_push_enabled" boolean) RETURNS SETOF "public"."notification_watch_areas"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_area_type text := upper(coalesce(nullif(trim(p_area_type), ''), 'CIRCLE'));
  v_center geography(Point, 4326);
  v_boundary geography(Polygon, 4326);
  v_radius_m integer;
  v_point_count integer;
begin
  if v_area_type not in ('CIRCLE', 'POLYGON') then
    raise exception 'INVALID_AREA_TYPE';
  end if;

  if v_area_type = 'CIRCLE' then
    if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
      raise exception 'INVALID_COORDINATES';
    end if;
    if p_radius_m is null or p_radius_m <= 0 or p_radius_m > 50000 then
      raise exception 'INVALID_RADIUS';
    end if;
    v_center := st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography;
    v_radius_m := p_radius_m;
  else
    if p_boundary_points is null or jsonb_typeof(p_boundary_points) <> 'array' then
      raise exception 'INVALID_BOUNDARY';
    end if;
    v_point_count := jsonb_array_length(p_boundary_points);
    if v_point_count < 3 or v_point_count > 100 then
      raise exception 'INVALID_BOUNDARY';
    end if;

    -- Use an explicit JSONB value alias. The previous function treated the
    -- table alias as a record when applying JSONB operators at runtime.
    if exists (
      select 1
      from jsonb_array_elements(p_boundary_points) as point_data(value)
      where not (point_data.value ? 'latitude')
         or not (point_data.value ? 'longitude')
         or jsonb_typeof(point_data.value->'latitude') <> 'number'
         or jsonb_typeof(point_data.value->'longitude') <> 'number'
         or (point_data.value->>'latitude')::double precision not between -90 and 90
         or (point_data.value->>'longitude')::double precision not between -180 and 180
    ) then
      raise exception 'INVALID_BOUNDARY_COORDINATES';
    end if;

    select st_makepolygon(st_makeline(array_agg(ordered.geom order by ordered.position)))::geography
      into v_boundary
    from (
      select point_data.position,
             st_setsrid(st_makepoint(
               (point_data.value->>'longitude')::double precision,
               (point_data.value->>'latitude')::double precision
             ), 4326) as geom
      from jsonb_array_elements(p_boundary_points)
        with ordinality as point_data(value, position)
      union all
      select v_point_count + 1,
             st_setsrid(st_makepoint(
               (p_boundary_points->0->>'longitude')::double precision,
               (p_boundary_points->0->>'latitude')::double precision
             ), 4326)
    ) as ordered;

    if v_boundary is null
       or not st_isvalid(v_boundary::geometry)
       or st_isempty(v_boundary::geometry)
       or st_area(v_boundary) <= 0 then
      raise exception 'INVALID_BOUNDARY';
    end if;

    v_center := st_centroid(v_boundary::geometry)::geography;
    v_radius_m := 1;
  end if;

  return query
  insert into public.notification_watch_areas(
    user_id, name, area_type, center, radius_m, boundary,
    category_keys, all_categories, push_enabled
  ) values (
    p_user_id, left(trim(p_name), 80), v_area_type, v_center,
    v_radius_m, v_boundary, coalesce(p_category_keys, '{}'::text[]),
    coalesce(p_all_categories, true), coalesce(p_push_enabled, true)
  ) returning *;
end;
$$;


ALTER FUNCTION "public"."create_user_watch_area_v2"("p_user_id" "uuid", "p_name" "text", "p_area_type" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_m" integer, "p_boundary_points" "jsonb", "p_category_keys" "text"[], "p_all_categories" boolean, "p_push_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_watch_area_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  saved_area_count integer;
begin
  if coalesce(new.source_type, 'SAVED') = 'CURRENT_LOCATION' then
    return new;
  end if;

  select count(*)
  into saved_area_count
  from public.notification_watch_areas
  where user_id = new.user_id
    and coalesce(source_type, 'SAVED') = 'SAVED';

  if saved_area_count >= 3 then
    raise exception 'WATCH_AREA_LIMIT_REACHED'
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_watch_area_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geo_alert_activation_state"("p_report_id" "uuid") RETURNS TABLE("active_until" timestamp with time zone, "activation_count" integer, "max_activations" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select max(e.current_period_end) filter (
           where e.status in ('ACTIVE', 'GRACE', 'PAUSED')
             and e.current_period_end > now()
         ) as active_until,
         (count(*) filter (
           where e.status in ('ACTIVE', 'GRACE', 'PAUSED', 'EXPIRED')
         ))::integer as activation_count,
         2 as max_activations
  from public.report_entitlements e
  where e.report_id = p_report_id
    and e.product_code like 'GEO_ALERT_TIER_%';
$$;


ALTER FUNCTION "public"."geo_alert_activation_state"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geo_alert_campaign_is_dispatchable"("p_campaign_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.geo_alert_campaigns c
    join public.reports r on r.id = c.report_id
    where c.id = p_campaign_id
      and upper(c.status::text) = 'ACTIVE'
      and coalesce(c.ends_at, now() + interval '1 minute') > now()
      and r.deleted_at is null
      and upper(r.status::text) = 'ACTIVE'
      and upper(r.type::text) = 'LOST'
  );
$$;


ALTER FUNCTION "public"."geo_alert_campaign_is_dispatchable"("p_campaign_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."report_entitlements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "report_id" "uuid" NOT NULL,
    "product_code" "text" NOT NULL,
    "order_id" "uuid",
    "status" "text" DEFAULT 'PENDING'::"text" NOT NULL,
    "starts_at" timestamp with time zone,
    "current_period_end" timestamp with time zone,
    "auto_renews" boolean DEFAULT false NOT NULL,
    "provider" "text",
    "provider_original_transaction_id" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cancelled_at" timestamp with time zone,
    "expired_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "report_entitlements_status_check" CHECK (("status" = ANY (ARRAY['PENDING'::"text", 'ACTIVE'::"text", 'GRACE'::"text", 'PAUSED'::"text", 'CANCELLED'::"text", 'REFUNDED'::"text", 'EXPIRED'::"text"])))
);


ALTER TABLE "public"."report_entitlements" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geo_alert_create_entitlement"("p_order_id" "uuid", "p_user_id" "uuid", "p_starts_at" timestamp with time zone, "p_period_end" timestamp with time zone, "p_provider" "text", "p_provider_transaction_id" "text", "p_metadata" "jsonb") RETURNS SETOF "public"."report_entitlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.report_orders%rowtype;
  v_state record;
  v_row   public.report_entitlements%rowtype;
begin
  select * into v_order
  from public.report_orders
  where id = p_order_id and user_id = p_user_id;
  if not found then
    raise exception using message = 'GEO_ALERT_ORDER_NOT_FOUND', errcode = 'P0001';
  end if;
  if v_order.product_code not like 'GEO_ALERT_TIER_%' then
    raise exception using message = 'GEO_ALERT_ORDER_INVALID_PRODUCT', errcode = 'P0001';
  end if;

  -- Serialize all activations for the same report.
  perform 1 from public.reports where id = v_order.report_id for update;
  if not found then
    raise exception using message = 'REPORT_NOT_FOUND', errcode = 'P0001';
  end if;

  -- Expire stale rows for this report so they neither block nor count as live.
  update public.report_entitlements
     set status = 'EXPIRED'
   where report_id = v_order.report_id
     and product_code like 'GEO_ALERT_TIER_%'
     and status in ('ACTIVE', 'GRACE', 'PAUSED')
     and current_period_end <= now();

  update public.geo_alert_campaigns
     set status = 'COMPLETED'
   where report_id = v_order.report_id
     and status = 'ACTIVE'
     and ends_at <= now();

  select * into v_state from public.geo_alert_activation_state(v_order.report_id);

  if v_state.active_until is not null then
    raise exception using
      message = 'GEO_ALERT_ALREADY_ACTIVE',
      detail  = to_char(v_state.active_until at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      errcode = 'P0001';
  end if;

  if v_state.activation_count >= v_state.max_activations then
    raise exception using
      message = 'GEO_ALERT_LIMIT_REACHED',
      detail  = v_state.activation_count::text,
      errcode = 'P0001';
  end if;

  insert into public.report_entitlements (
    user_id, report_id, product_code, order_id, status,
    starts_at, current_period_end, auto_renews,
    provider, provider_original_transaction_id, metadata
  ) values (
    p_user_id, v_order.report_id, v_order.product_code, v_order.id, 'ACTIVE',
    p_starts_at, p_period_end, false,
    coalesce(p_provider, 'TEST'), p_provider_transaction_id, coalesce(p_metadata, '{}'::jsonb)
  )
  returning * into v_row;

  return next v_row;
end;
$$;


ALTER FUNCTION "public"."geo_alert_create_entitlement"("p_order_id" "uuid", "p_user_id" "uuid", "p_starts_at" timestamp with time zone, "p_period_end" timestamp with time zone, "p_provider" "text", "p_provider_transaction_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geo_alert_create_in_app_notifications"("p_campaign_id" "uuid") RETURNS TABLE("eligible_users" integer, "created_notifications" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with eligible as (
    select * from public.geo_alert_eligible_users(p_campaign_id)
  ),
  inserted as (
    insert into public.notifications
      (user_id, type, entity_type, entity_id, title, body, notification_key, agg_count)
    select e.recipient_user_id,
           'AREA_ALERT',
           'area_alert_campaign',
           e.campaign_id,
           'AREA_ALERT',
           coalesce(e.report_title, 'AREA_ALERT'),
           'AREA_ALERT:' || e.campaign_id::text || ':' || e.recipient_user_id::text,
           1
    from eligible e
    on conflict (notification_key) where notification_key is not null do nothing
    returning 1
  )
  select (select count(*) from eligible)::integer,
         (select count(*) from inserted)::integer;
$$;


ALTER FUNCTION "public"."geo_alert_create_in_app_notifications"("p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geo_alert_eligible_installations"("p_campaign_id" "uuid") RETURNS TABLE("campaign_id" "uuid", "recipient_user_id" "uuid", "installation_id" "text", "expo_push_token" "text", "language" "text", "watch_area_id" "uuid", "report_id" "uuid", "report_title" "text", "category_key" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select distinct on (pi.installation_id)
         u.campaign_id,
         u.recipient_user_id,
         pi.installation_id,
         pi.expo_push_token,
         pi.language,
         u.watch_area_id,
         u.report_id,
         u.report_title,
         u.category_key
  from public.geo_alert_eligible_users(p_campaign_id) u
  join public.push_installations pi
    on pi.user_id = u.recipient_user_id
   and pi.active = true
   and pi.permission_status = 'granted'
  where u.push_requested = true
  order by pi.installation_id, pi.last_seen_at desc, u.recipient_user_id;
$$;


ALTER FUNCTION "public"."geo_alert_eligible_installations"("p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geo_alert_eligible_users"("p_campaign_id" "uuid") RETURNS TABLE("campaign_id" "uuid", "recipient_user_id" "uuid", "watch_area_id" "uuid", "push_requested" boolean, "report_id" "uuid", "report_title" "text", "category_key" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with campaign as (
    select c.id,
           c.report_id,
           c.geometry,
           c.radius_m,
           r.user_id as report_owner_id,
           r.title   as report_title,
           upper(coalesce(r.category::text, '')) as category_key
    from public.geo_alert_campaigns c
    join public.reports r on r.id = c.report_id
    where c.id = p_campaign_id
      and upper(c.status::text) = 'ACTIVE'
      and coalesce(c.ends_at, now() + interval '1 minute') > now()
      and r.deleted_at is null
      and upper(r.status::text) = 'ACTIVE'
      and upper(r.type::text) = 'LOST'
  ),
  qualifying as (
    select c.id as campaign_id, q.recipient_user_id, q.watch_area_id, q.push_enabled,
           q.watch_area_updated_at, c.report_id, c.report_title, c.category_key
    from campaign c
    cross join lateral public.geo_alert_qualifying_users(
      c.report_owner_id, c.geometry::geography, c.radius_m, c.category_key) q
  )
  select distinct on (q.recipient_user_id)
         q.campaign_id,
         q.recipient_user_id,
         q.watch_area_id,
         bool_or(q.push_enabled) over (partition by q.recipient_user_id) as push_requested,
         q.report_id,
         q.report_title,
         q.category_key
  from qualifying q
  order by q.recipient_user_id,
           q.push_enabled desc,
           q.watch_area_updated_at desc,
           q.watch_area_id;
$$;


ALTER FUNCTION "public"."geo_alert_eligible_users"("p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geo_alert_qualifying_users"("p_owner_id" "uuid", "p_point" "public"."geography", "p_radius_m" integer, "p_category_key" "text") RETURNS TABLE("recipient_user_id" "uuid", "watch_area_id" "uuid", "push_enabled" boolean, "watch_area_updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select wa.user_id, wa.id, wa.push_enabled, wa.updated_at
  from public.notification_watch_areas wa
  where p_point is not null
    and wa.active = true
    and (wa.expires_at is null or wa.expires_at > now())
    and wa.user_id <> p_owner_id
    and (wa.all_categories = true
         or upper(coalesce(p_category_key, '')) = any(coalesce(wa.category_keys, '{}'::text[])))
    and case
          when wa.area_type = 'POLYGON'
            then st_dwithin(wa.boundary, p_point, coalesce(p_radius_m, 0))
          else st_dwithin(wa.center, p_point, wa.radius_m + coalesce(p_radius_m, 0))
        end;
$$;


ALTER FUNCTION "public"."geo_alert_qualifying_users"("p_owner_id" "uuid", "p_point" "public"."geography", "p_radius_m" integer, "p_category_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_matches_for_report"("p_report_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "score" integer, "status" "public"."match_status", "reasons" "jsonb", "lost_id" "uuid", "found_id" "uuid", "lost_title" "text", "lost_reward_ore" integer, "found_title" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    m.id,
    m.score,
    m.status,
    m.reasons,
    m.lost_id,
    m.found_id,
    l.title AS lost_title,
    COALESCE(l.reward_ore, 0) AS lost_reward_ore,
    f.title AS found_title
  FROM public.matches m
  JOIN public.reports l ON l.id = m.lost_id
  JOIN public.reports f ON f.id = m.found_id
  WHERE m.lost_id = p_report_id OR m.found_id = p_report_id
  ORDER BY m.score DESC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."get_matches_for_report"("p_report_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_watch_areas"("p_user_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "area_type" "text", "latitude" double precision, "longitude" double precision, "radius_m" integer, "boundary_points" "jsonb", "category_keys" "text"[], "all_categories" boolean, "push_enabled" boolean, "active" boolean, "source_type" "text", "expires_at" timestamp with time zone, "location_updated_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
 select a.id,a.name,a.area_type,st_y(a.center::geometry),st_x(a.center::geometry),case when a.area_type='CIRCLE' then a.radius_m else null end,
 case when a.boundary is null then '[]'::jsonb else (select jsonb_agg(jsonb_build_object('latitude',st_y((d).geom),'longitude',st_x((d).geom)) order by (d).path) from st_dumppoints(st_exteriorring(a.boundary::geometry)) d where (d).path[array_length((d).path,1)] < st_npoints(st_exteriorring(a.boundary::geometry))) end,
 a.category_keys,a.all_categories,a.push_enabled,a.active,a.source_type,a.expires_at,a.location_updated_at,a.created_at,a.updated_at
 from public.notification_watch_areas a where a.user_id=p_user_id and (a.expires_at is null or a.expires_at>now()) order by case when a.source_type='CURRENT_LOCATION' then 0 else 1 end,a.created_at;
$$;


ALTER FUNCTION "public"."get_user_watch_areas"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_new_match_to_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner_user uuid;
  v_existing_id uuid;
  v_existing_read_at timestamptz;
  v_existing_count int;
  v_new_count int;
begin
  -- Kun topp 3 nivåer: score >= 55.
  -- Lav sannsynlighet (score < 55) er helt skjult og skal aldri varsles.
  if new.score is null or new.score < 55 then
    return new;
  end if;

  -- Kun MISTET skal motta varsel (anti-misbruk):
  -- varsle eier av lost_id (lost report)
  select r.user_id
    into v_owner_user
  from public.reports r
  where r.id = new.lost_id;

  if v_owner_user is null then
    return new;
  end if;

  -- Samle: 1 notif per (user + lost_id)
  select n.id, n.read_at, coalesce(n.agg_count, 1)
    into v_existing_id, v_existing_read_at, v_existing_count
  from public.notifications n
  where n.user_id = v_owner_user
    and n.type = 'NEW_MATCH'
    and n.entity_type = 'report'
    and n.entity_id = new.lost_id
  order by n.created_at desc
  limit 1;

  if v_existing_id is not null then
    -- Hvis ulest: tell opp. Hvis lest: start på 1 igjen.
    if v_existing_read_at is null then
      v_new_count := v_existing_count + 1;
    else
      v_new_count := 1;
    end if;

    update public.notifications
    set
      agg_count = v_new_count,
      title = case when v_new_count > 1 then 'Nye matcher' else 'Ny match' end,
      body  = case
                when v_new_count > 1
                then 'Du har fått ' || v_new_count || ' nye matcher for rapporten din. Åpne Matcher for detaljer.'
                else 'Du har fått en ny kandidat for rapporten din. Åpne Matcher for detaljer.'
              end,
      read_at = null,
      created_at = now()
    where id = v_existing_id;

  else
    insert into public.notifications (user_id, type, entity_type, entity_id, title, body, agg_count)
    values (
      v_owner_user,
      'NEW_MATCH',
      'report',
      new.lost_id,
      'Ny match',
      'Du har fått en ny kandidat for rapporten din. Åpne Matcher for detaljer.',
      1
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_new_match_to_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_new_message_to_notifications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_lost_id uuid;
  v_found_id uuid;
  v_lost_user uuid;
  v_found_user uuid;
  v_recipient uuid;
  v_body text;
  v_existing_id uuid;
begin
  -- Må ha conversation_id og sender_id
  if new.conversation_id is null or new.sender_id is null then
    return new;
  end if;

  -- Finn match (matches.id = messages.conversation_id)
  select m.lost_id, m.found_id
    into v_lost_id, v_found_id
  from public.matches m
  where m.id = new.conversation_id;

  if v_lost_id is null and v_found_id is null then
    return new;
  end if;

  -- Finn eierne av rapportene
  select r.user_id into v_lost_user
  from public.reports r
  where r.id = v_lost_id;

  select r.user_id into v_found_user
  from public.reports r
  where r.id = v_found_id;

  -- Bestem mottaker = den andre brukeren
  if v_lost_user is not null and v_lost_user = new.sender_id then
    v_recipient := v_found_user;
  elsif v_found_user is not null and v_found_user = new.sender_id then
    v_recipient := v_lost_user;
  else
    return new;
  end if;

  if v_recipient is null then
    return new;
  end if;

  -- Kort ned body
  v_body := coalesce(new.body, '');
  v_body := regexp_replace(v_body, '\s+', ' ', 'g');
  if length(v_body) > 140 then
    v_body := substring(v_body from 1 for 137) || '...';
  end if;

  -- Finn eksisterende notification for samme mottaker + samme match (entity_id)
  select n.id
    into v_existing_id
  from public.notifications n
  where n.user_id = v_recipient
    and n.type = 'NEW_MESSAGE'
    and n.entity_type = 'match'
    and n.entity_id = new.conversation_id
  order by n.created_at desc
  limit 1;

  if v_existing_id is not null then
    -- MERGE: oppdater eksisterende rad (ingen spam)
    update public.notifications
    set
      title = 'Ny melding',
      body = v_body,
      read_at = null,
      created_at = now()
    where id = v_existing_id;
  else
    -- Første gang: insert
    insert into public.notifications (user_id, type, entity_type, entity_id, title, body)
    values (
      v_recipient,
      'NEW_MESSAGE',
      'match',
      new.conversation_id,
      'Ny melding',
      v_body
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_new_message_to_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."object_compatibility_level"("a" "text", "b" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN a IS NULL OR b IS NULL THEN 1
    WHEN upper(a)=upper(b) THEN 3
    WHEN upper(a) LIKE 'OTHER%' OR upper(b) LIKE 'OTHER%' OR upper(a)='CUSTOM' OR upper(b)='CUSTOM' THEN 1
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['RING','WEDDING_RING','ENGAGEMENT_RING','SIGNET_RING'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['WATCH','SMARTWATCH','SPORT_WATCH','FITNESS_TRACKER'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['HEADPHONES','EARBUDS'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['DISC_GOLF_DISC','DISC_GOLF_DRIVER','DISC_GOLF_MIDRANGE','DISC_GOLF_PUTTER'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['SWEATER','HOODIE','CARDIGAN','FLEECE'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['JACKET','RAIN_JACKET','DOWN_JACKET','FLEECE_JACKET'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['CAMERA','ACTION_CAMERA'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['BACKPACK','HIKING_BACKPACK','SCHOOL_BAG','CHILD_BACKPACK'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['GYM_BAG','SPORTS_BAG','TRAVEL_BAG'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['BICYCLE','E_BIKE'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['SCOOTER','E_SCOOTER'] THEN 2
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['HELMET','BIKE_HELMET','MOTORCYCLE_HELMET'] THEN 1
    WHEN (upper(a) IN ('SWEATER','HOODIE','CARDIGAN','FLEECE') AND upper(b) IN ('JACKET','FLEECE_JACKET'))
      OR (upper(b) IN ('SWEATER','HOODIE','CARDIGAN','FLEECE') AND upper(a) IN ('JACKET','FLEECE_JACKET')) THEN 1
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['SHOES','SNEAKERS','BOOTS','SANDALS'] THEN 1
    WHEN ARRAY[upper(a),upper(b)] <@ ARRAY['SUITCASE','CABIN_SUITCASE','TRAVEL_LUGGAGE'] THEN 2
    ELSE 0 END;
$$;


ALTER FUNCTION "public"."object_compatibility_level"("a" "text", "b" "text") OWNER TO "postgres";


