CREATE OR REPLACE FUNCTION "public"."preview_geo_alert_audience"("p_report_id" "uuid", "p_user_id" "uuid", "p_radius_m" integer) RETURNS TABLE("report_id" "uuid", "latitude" double precision, "longitude" double precision, "radius_m" integer, "area_sq_km" numeric, "category_key" "text", "eligible_users" integer, "eligible_installations" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with report_source as (
    select r.id,
           r.user_id,
           r.lat::double precision as latitude,
           r.lng::double precision as longitude,
           upper(coalesce(r.category::text, '')) as category_key,
           st_setsrid(st_makepoint(r.lng::double precision, r.lat::double precision), 4326)::geography as point
    from public.reports r
    where r.id = p_report_id
      and r.user_id = p_user_id
      and r.deleted_at is null
      and upper(r.type::text) = 'LOST'
      and r.lat is not null
      and r.lng is not null
  ),
  users as (
    select q.recipient_user_id, bool_or(q.push_enabled) as push_requested
    from report_source rs
    cross join lateral public.geo_alert_qualifying_users(rs.user_id, rs.point, p_radius_m, rs.category_key) q
    group by q.recipient_user_id
  ),
  installs as (
    select distinct pi.installation_id
    from users u
    join public.push_installations pi
      on pi.user_id = u.recipient_user_id
     and pi.active = true
     and pi.permission_status = 'granted'
    where u.push_requested = true
  )
  select rs.id,
         rs.latitude,
         rs.longitude,
         p_radius_m,
         round((pi() * p_radius_m * p_radius_m / 1000000.0)::numeric, 4),
         rs.category_key,
         (select count(*) from users)::integer,
         (select count(*) from installs)::integer
  from report_source rs
  where p_radius_m between 250 and 50000;
$$;


ALTER FUNCTION "public"."preview_geo_alert_audience"("p_report_id" "uuid", "p_user_id" "uuid", "p_radius_m" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_commerce_expiry"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_now timestamptz := now();
  v_entitlements integer := 0;
  v_campaigns integer := 0;
  v_active_orders integer := 0;
  v_stale_orders integer := 0;
begin
  update public.report_entitlements e
     set status = 'EXPIRED'
   where e.status in ('ACTIVE', 'GRACE', 'PAUSED')
     and coalesce(e.auto_renews, false) = false
     and e.current_period_end is not null
     and e.current_period_end <= v_now;
  get diagnostics v_entitlements = row_count;

  update public.geo_alert_campaigns c
     set status = 'COMPLETED',
         completed_at = coalesce(c.completed_at, v_now),
         updated_at = v_now
   where upper(c.status::text) = 'ACTIVE'
     and c.ends_at is not null
     and c.ends_at <= v_now;
  get diagnostics v_campaigns = row_count;

  update public.report_orders o
     set status = 'EXPIRED', updated_at = v_now
   where o.status = 'ACTIVE'
     and exists (select 1 from public.report_entitlements e
                 where e.order_id = o.id and e.status = 'EXPIRED')
     and not exists (select 1 from public.report_entitlements e
                     where e.order_id = o.id and e.status in ('ACTIVE', 'GRACE', 'PAUSED'));
  get diagnostics v_active_orders = row_count;

  update public.report_orders o
     set status = 'EXPIRED', updated_at = v_now
   where o.status in ('PENDING', 'AUTHORIZED')
     and o.created_at < v_now - interval '24 hours';
  get diagnostics v_stale_orders = row_count;

  return jsonb_build_object(
    'expired_entitlements', v_entitlements,
    'completed_campaigns', v_campaigns,
    'expired_active_orders', v_active_orders,
    'expired_stale_orders', v_stale_orders
  );
end;
$$;


ALTER FUNCTION "public"."process_commerce_expiry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_report_lifecycle"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_run_id uuid;
  v_now timestamptz := now();
  v_expired_lost integer := 0;
  v_expired_found integer := 0;
  v_archived_found integer := 0;
  v_expiring_notifications integer := 0;
  v_expired_notifications integer := 0;
  v_archived_notifications integer := 0;
begin
  insert into public.report_lifecycle_runs(started_at)
  values (v_now)
  returning id into v_run_id;

  -- Warnings: LOST 3 days before expiry; FOUND 7 days before expiry.
  insert into public.notifications
    (user_id, type, entity_type, entity_id, title, body, created_at, notification_key)
  select
    r.user_id,
    'REPORT_EXPIRING',
    'report',
    r.id,
    case when r.type = 'LOST' then 'Saken utløper snart' else 'Funnrapporten utløper snart' end,
    case when r.type = 'LOST'
      then 'Mistet-rapporten nærmer seg slutten av synlighetsperioden.'
      else 'Har du fortsatt gjenstanden? Funnrapporten kan snart forlenges.'
    end,
    v_now,
    'REPORT_EXPIRING:' || r.id::text || ':' || to_char(r.visible_until at time zone 'UTC', 'YYYYMMDDHH24MISS')
  from public.reports r
  where r.deleted_at is null
    and r.closed_at is null
    and r.archived_at is null
    and r.status = 'ACTIVE'
    and r.user_id is not null
    and r.visible_until is not null
    and r.visible_until > v_now
    and (
      (r.type = 'LOST' and r.visible_until <= v_now + interval '3 days')
      or
      (r.type = 'FOUND' and r.visible_until <= v_now + interval '7 days')
    )
  on conflict (notification_key) where notification_key is not null do nothing;
  get diagnostics v_expiring_notifications = row_count;

  -- Expire LOST. Return changed rows for one notification per transition.
  with changed as (
    update public.reports r
       set status = 'EXPIRED'
     where r.type = 'LOST'
       and r.status = 'ACTIVE'
       and r.deleted_at is null
       and r.closed_at is null
       and r.archived_at is null
       and r.visible_until is not null
       and r.visible_until <= v_now
    returning r.id, r.user_id, r.visible_until
  ), notified as (
    insert into public.notifications
      (user_id, type, entity_type, entity_id, title, body, created_at, notification_key)
    select
      c.user_id, 'REPORT_EXPIRED', 'report', c.id,
      'Saken er utløpt',
      'Mistet-rapporten deltar ikke lenger i nye treff, men beholdes i historikken din.',
      v_now,
      'REPORT_EXPIRED:' || c.id::text || ':' || to_char(c.visible_until at time zone 'UTC', 'YYYYMMDDHH24MISS')
    from changed c
    where c.user_id is not null
    on conflict (notification_key) where notification_key is not null do nothing
    returning 1
  )
  select
    (select count(*) from changed),
    (select count(*) from notified)
  into v_expired_lost, v_expired_notifications;

  -- Expire FOUND when visible period ends.
  with changed as (
    update public.reports r
       set status = 'EXPIRED'
     where r.type = 'FOUND'
       and r.status = 'ACTIVE'
       and r.deleted_at is null
       and r.closed_at is null
       and r.archived_at is null
       and r.visible_until is not null
       and r.visible_until <= v_now
    returning r.id, r.user_id, r.visible_until
  ), notified as (
    insert into public.notifications
      (user_id, type, entity_type, entity_id, title, body, created_at, notification_key)
    select
      c.user_id, 'REPORT_EXPIRED', 'report', c.id,
      'Funnrapporten er utløpt',
      'Funnrapporten deltar ikke lenger i nye treff. Åpne Mine saker for å se om den kan aktiveres igjen.',
      v_now,
      'REPORT_EXPIRED:' || c.id::text || ':' || to_char(c.visible_until at time zone 'UTC', 'YYYYMMDDHH24MISS')
    from changed c
    where c.user_id is not null
    on conflict (notification_key) where notification_key is not null do nothing
    returning 1
  )
  select
    (select count(*) from changed),
    v_expired_notifications + (select count(*) from notified)
  into v_expired_found, v_expired_notifications;

  -- Archive only final FOUND reports: 90 days old, or both extensions used after expiry.
  with changed as (
    update public.reports r
       set status = 'ARCHIVED',
           archived_at = coalesce(r.archived_at, v_now)
     where r.type = 'FOUND'
       and r.status = 'EXPIRED'
       and r.deleted_at is null
       and r.closed_at is null
       and r.archived_at is null
       and (
         r.created_at <= v_now - interval '90 days'
         or coalesce(r.extension_count, 0) >= 2
       )
    returning r.id, r.user_id
  ), notified as (
    insert into public.notifications
      (user_id, type, entity_type, entity_id, title, body, created_at, notification_key)
    select
      c.user_id, 'REPORT_ARCHIVED', 'report', c.id,
      'Funnrapporten er arkivert',
      'Rapporten beholdes i historikken, men kan ikke lenger forlenges eller få nye treff.',
      v_now,
      'REPORT_ARCHIVED:' || c.id::text
    from changed c
    where c.user_id is not null
    on conflict (notification_key) where notification_key is not null do nothing
    returning 1
  )
  select
    (select count(*) from changed),
    (select count(*) from notified)
  into v_archived_found, v_archived_notifications;

  update public.report_lifecycle_runs
     set finished_at = clock_timestamp(),
         expired_lost_count = v_expired_lost,
         expired_found_count = v_expired_found,
         archived_found_count = v_archived_found,
         expiring_notification_count = v_expiring_notifications,
         expired_notification_count = v_expired_notifications,
         archived_notification_count = v_archived_notifications,
         ok = true
   where id = v_run_id;

  return jsonb_build_object(
    'run_id', v_run_id,
    'expired_lost', v_expired_lost,
    'expired_found', v_expired_found,
    'archived_found', v_archived_found,
    'expiring_notifications', v_expiring_notifications,
    'expired_notifications', v_expired_notifications,
    'archived_notifications', v_archived_notifications
  );
exception when others then
  update public.report_lifecycle_runs
     set finished_at = clock_timestamp(), ok = false, error_message = sqlerrm
   where id = v_run_id;
  raise;
end;
$$;


ALTER FUNCTION "public"."process_report_lifecycle"() OWNER TO "postgres";


