CREATE OR REPLACE FUNCTION "public"."profile_upsert"("p_display_name" "text", "p_avatar_url" "text" DEFAULT NULL::"text") RETURNS "public"."profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_row public.profiles;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  insert into public.profiles as p (id, display_name, avatar_url)
  values (v_uid, coalesce(p_display_name, ''), p_avatar_url)
  on conflict (id) do update
    set display_name = excluded.display_name,
        avatar_url   = excluded.avatar_url,
        updated_at   = now()
  returning * into v_row;

  return v_row;
end;
$$;


