CREATE OR REPLACE FUNCTION "public"."report_search_area_contains"("p_report_id" "uuid", "p_lat" double precision, "p_lng" double precision) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_areas jsonb;
  v_area jsonb;
  v_kind text;
  v_points jsonb;
  v_radius_m double precision;
  v_target geometry;
  v_shape geometry;
begin
  if p_report_id is null or p_lat is null or p_lng is null then
    return false;
  end if;

  select coalesce(r.search_areas, '[]'::jsonb)
    into v_areas
  from public.reports r
  where r.id = p_report_id
    and r.deleted_at is null;

  if v_areas is null or jsonb_typeof(v_areas) <> 'array' or jsonb_array_length(v_areas) = 0 then
    return false;
  end if;

  v_target := st_setsrid(st_makepoint(p_lng, p_lat), 4326);

  for v_area in
    select value from jsonb_array_elements(v_areas)
  loop
    v_kind := upper(coalesce(v_area ->> 'kind', ''));
    v_points := coalesce(v_area -> 'points', '[]'::jsonb);
    v_radius_m := greatest(10, least(100000, coalesce((v_area ->> 'radiusMeters')::double precision, 500)));

    if v_kind = 'CIRCLE' and jsonb_array_length(v_points) = 1 then
      v_shape := st_setsrid(
        st_makepoint(
          (v_points -> 0 ->> 'longitude')::double precision,
          (v_points -> 0 ->> 'latitude')::double precision
        ),
        4326
      );

      if st_dwithin(v_target::geography, v_shape::geography, v_radius_m) then
        return true;
      end if;

    elsif v_kind = 'ROUTE' and jsonb_array_length(v_points) >= 2 then
      select st_setsrid(
        st_makeline(
          st_makepoint(
            (point ->> 'longitude')::double precision,
            (point ->> 'latitude')::double precision
          )
          order by ordinality
        ),
        4326
      )
      into v_shape
      from jsonb_array_elements(v_points) with ordinality as route_point(point, ordinality);

      if st_dwithin(v_target::geography, v_shape::geography, v_radius_m) then
        return true;
      end if;

    elsif v_kind = 'POLYGON' and jsonb_array_length(v_points) >= 3 then
      select st_setsrid(
        st_makepolygon(
          st_addpoint(
            st_makeline(
              st_makepoint(
                (point ->> 'longitude')::double precision,
                (point ->> 'latitude')::double precision
              )
              order by ordinality
            ),
            st_makepoint(
              (v_points -> 0 ->> 'longitude')::double precision,
              (v_points -> 0 ->> 'latitude')::double precision
            )
          )
        ),
        4326
      )
      into v_shape
      from jsonb_array_elements(v_points) with ordinality as polygon_point(point, ordinality);

      if st_covers(v_shape, v_target) then
        return true;
      end if;
    end if;
  end loop;

  return false;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return false;
end;
$$;


ALTER FUNCTION "public"."report_search_area_contains"("p_report_id" "uuid", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_search_area_distance_m"("p_report_id" "uuid", "p_lat" double precision, "p_lng" double precision) RETURNS double precision
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_areas jsonb;
  v_area jsonb;
  v_kind text;
  v_points jsonb;
  v_target geometry;
  v_shape geometry;
  v_distance double precision;
  v_best double precision := null;
begin
  if p_report_id is null or p_lat is null or p_lng is null then return null; end if;
  select coalesce(search_areas, '[]'::jsonb) into v_areas
  from public.reports where id = p_report_id and deleted_at is null;
  if v_areas is null or jsonb_typeof(v_areas) <> 'array' or jsonb_array_length(v_areas) = 0 then return null; end if;
  v_target := st_setsrid(st_makepoint(p_lng, p_lat), 4326);

  for v_area in select value from jsonb_array_elements(v_areas)
  loop
    v_kind := upper(coalesce(v_area->>'kind',''));
    v_points := coalesce(v_area->'points','[]'::jsonb);
    if v_kind = 'CIRCLE' and jsonb_array_length(v_points) = 1 then
      v_shape := st_setsrid(st_makepoint((v_points->0->>'longitude')::double precision,(v_points->0->>'latitude')::double precision),4326);
      v_distance := st_distance(v_target::geography,v_shape::geography);
    elsif v_kind = 'ROUTE' and jsonb_array_length(v_points) >= 2 then
      select st_setsrid(st_makeline(st_makepoint((point->>'longitude')::double precision,(point->>'latitude')::double precision) order by ordinality),4326)
      into v_shape from jsonb_array_elements(v_points) with ordinality as q(point,ordinality);
      v_distance := st_distance(v_target::geography,v_shape::geography);
    elsif v_kind = 'POLYGON' and jsonb_array_length(v_points) >= 3 then
      select st_setsrid(st_makepolygon(st_addpoint(st_makeline(st_makepoint((point->>'longitude')::double precision,(point->>'latitude')::double precision) order by ordinality),st_makepoint((v_points->0->>'longitude')::double precision,(v_points->0->>'latitude')::double precision))),4326)
      into v_shape from jsonb_array_elements(v_points) with ordinality as q(point,ordinality);
      v_distance := st_distance(v_target::geography,v_shape::geography);
    else
      continue;
    end if;
    if v_best is null or v_distance < v_best then v_best := v_distance; end if;
  end loop;
  return v_best;
exception when invalid_text_representation or numeric_value_out_of_range then return null;
end;
$$;


ALTER FUNCTION "public"."report_search_area_distance_m"("p_report_id" "uuid", "p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


