    LANGUAGE "plpgsql"
    AS $$
begin
  if new.lat is not null and new.lng is not null then
    new.location :=
      ST_SetSRID(
        ST_MakePoint(new.lng, new.lat),
        4326
      )::geography;
  end if;
  return new;
end;
$$;


