CREATE POLICY "conversation access via match" ON "public"."conversations" FOR SELECT USING ((EXISTS ( SELECT 1
   FROM (("public"."matches" "m"
     JOIN "public"."reports" "r1" ON (("r1"."id" = "m"."lost_id")))
     JOIN "public"."reports" "r2" ON (("r2"."id" = "m"."found_id")))
  WHERE (("m"."id" = "conversations"."id") AND ("m"."status" = 'CONFIRMED'::"public"."match_status") AND (("r1"."user_id" = "auth"."uid"()) OR ("r2"."user_id" = "auth"."uid"()))))));



