ALTER TABLE "public"."push_installations" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "read messages in own conversation" ON "public"."messages" FOR SELECT USING ((EXISTS ( SELECT 1
   FROM ((("public"."conversations" "c"
     JOIN "public"."matches" "m" ON (("m"."id" = "c"."id")))
     JOIN "public"."reports" "r1" ON (("r1"."id" = "m"."lost_id")))
     JOIN "public"."reports" "r2" ON (("r2"."id" = "m"."found_id")))
  WHERE (("c"."id" = "messages"."conversation_id") AND ("m"."status" = 'CONFIRMED'::"public"."match_status") AND (("r1"."user_id" = "auth"."uid"()) OR ("r2"."user_id" = "auth"."uid"()))))));



